import {TYPES,EVENTS,metrics,local,advance,neighbors} from './engine.mjs';
const mgmt=cell=>`background-image:url('assets/manejo-paisagem.webp');background-size:300% 200%;background-position:${cell%3*50}% ${Math.floor(cell/3)*100}%;`;
const paths={pipes:'M8 18H92M8 37H92M8 56H92M8 75H92M8 94H92M8 13V95',roots:'M28 48V68l-9 15m9-18 12 15m12-34v29l-10 14m10-18 11 13m13-37v22l-8 15m8-16 8 11',paddocks:'M33 0V100M66 0V100M0 50H100',trail:'M8 94Q22 70 45 67T69 36T92 10'};
export function sceneSpec(s,id){const t=s.tiles[id];let base=`background-position:${TYPES[t.type].atlas%3*50}% ${Math.floor(TYPES[t.type].atlas/3)*100}%;`,key=t.type,layers=[],labels=[];
 if(t.type==='crop'){base="background-image:url('assets/cultivo.webp');background-size:cover;background-position:center;";if(t.cover){base=mgmt(0);key='mulch';labels.push('Palhada na superfície');}else if(t.cropRotation){base=mgmt(3);key='rotation';labels.push('Cultivos alternados');}else if(t.irrigation){base=mgmt(2);key='drip';}else if(t.bio){base=mgmt(1);key='flowers';}}
 if(t.type==='forest'&&t.maturity<3){base=mgmt(5);key='young-native';labels.push('Vegetação em implantação');}
 if(t.type==='agro'&&t.maturity<2){base=mgmt(5);key='young-agro';labels.push('Árvores em implantação');}
 if(t.type==='silvo'){base=mgmt(t.maturity<2?5:4);key=t.maturity<2?'young-silvo':'silvopasture';labels.push(t.maturity<2?'Árvores plantadas':'Árvores e forragem');}
 if(t.cover){layers.push('mulch');if(!labels.includes('Palhada na superfície'))labels.push('Palhada na superfície');}
 if(t.cropRotation){layers.push('rotation');labels.push('Diversificação dos cultivos');}
 if(t.noTill){layers.push('notill');labels.push('Sulcos sem revolvimento amplo');}
 if(t.bio){layers.push('flowers',t.toxic?'pollination-low':'pollination');labels.push(t.toxic?'Faixas floridas sob exposição':'Faixas floridas e refúgios');}
 if(t.irrigation){layers.push('drip');labels.push('Gotejamento em atividade');}
 if(t.compost){layers.push('compost','roots');labels.push('Matéria orgânica no solo');}
 if(t.bioGrowth){layers.push('growth','roots');labels.push('Agentes nas raízes');}
 if(t.microbial){layers.push('microbial');labels.push('Agente de controle aplicado');}
 if(t.mip){layers.push('monitor');labels.push('Monitoramento ativo');}
 if(t.fertilizer){layers.push('nutrients');labels.push('Nutrientes adicionados');}
 if(t.toxic){layers.push('spray');labels.push('Inseticida e resíduos ativos');}
 if(t.rotation){layers.push('paddocks');labels.push('Piquetes com descanso');}
 if(t.timberCooldown&&t.type==='forest'){layers.push('clearings');labels.push('Clareiras de retirada seletiva');}
 if(t.gather){layers.push('harvest');labels.push('Coleta organizada');}
 if(t.trail){layers.push('trail');labels.push('Trilha de visitação');}
 if(t.type==='wetland'){layers.push('water');if(t.nursery){layers.push('nursery');labels.push('Refúgio de reprodução');}if(t.intensiveFish){layers.push('fishing');labels.push('Captura ampliada');}if(t.bank){layers.push('bank');labels.push('Vegetação na margem');}}
 if(t.type==='village'){if(s.sanitation){layers.push('treatment');labels.push('Efluentes tratados');}if(s.cooperative){layers.push('cooperative');labels.push('Rede de compras');}if(s.brigade){layers.push('brigade');labels.push('Brigada organizada');}}
 if(t.soil<45&&['crop','pasture'].includes(t.type)){layers.push('dry');labels.push('Solo sob pressão');}
 return {base,key,layers:[...new Set(layers)],labels:[...new Set(labels)],soil:t.soil,maturity:t.maturity};}
function svg(content,cls=''){return `<svg class="scene-svg ${cls}" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${content}</svg>`;}
function particleField(cls,count=9){return `<span class="particle-field ${cls}">${Array.from({length:count},(_,i)=>`<i style="--x:${13+(i*29)%76}%;--y:${19+(i*17)%64}%;--d:${(i%5)*.3}s"></i>`).join('')}</span>`;}
function layerHTML(name,compact){switch(name){
 case 'drip':return svg(`<path d="${paths.pipes}" fill="none" stroke="#172330" stroke-width="1.1"/><path class="water-flow" d="${paths.pipes}" fill="none" stroke="#8de3ff" stroke-width=".55" stroke-dasharray="1 8"/>`,'drip-pipes');
 case 'paddocks':return svg(`<path d="${paths.paddocks}" fill="none" stroke="#eee8cf" stroke-width="1.15"/><path d="M33 0v100M66 0v100" stroke="#403a24" stroke-width=".4" stroke-dasharray="1 5"/><rect x="35" y="2" width="29" height="46" fill="#81c26a" opacity=".18"/>`);
 case 'notill':return svg('<path class="seeding-line" d="M2 25H98M2 49H98M2 73H98" stroke="#f6dfae" stroke-width=".8" stroke-dasharray="2 2"/>');
 case 'roots':return svg(`<path class="root-flow" d="${paths.roots}" fill="none" stroke="#ffdc91" stroke-width=".65" stroke-dasharray="3 2"/>`,'root-system');
 case 'trail':return svg(`<path d="${paths.trail}" fill="none" stroke="#4e341d" stroke-width="2.3"/><path d="${paths.trail}" fill="none" stroke="#dec794" stroke-width="1.4" stroke-dasharray="1 .3"/>`);
 case 'mulch':return '<span class="straw-texture"></span>';
 case 'rotation':return '<span class="rotation-strips"></span>';
 case 'flowers':return '<span class="flower-borders"></span>';
 case 'pollination':return particleField('pollinator-flow',compact?4:9);
 case 'pollination-low':return particleField('pollinator-flow pollination-low',compact?1:3);
 case 'compost':return '<span class="compost-texture"></span>';
 case 'growth':return particleField('growth-agents',compact?4:10);
 case 'microbial':return particleField('microbe-agents',compact?4:10);
 case 'nutrients':return particleField('nutrient-flow',compact?4:10);
 case 'spray':return '<span class="spray-pass"></span><span class="residue-haze"></span>';
 case 'monitor':return svg('<circle class="monitor-ring" cx="40" cy="42" r="15" fill="none" stroke="#ffcc74" stroke-width=".6"/><path d="M40 21v8m0 26v8M19 42h8m26 0h8" stroke="#ffcc74" stroke-width=".7"/>');
 case 'clearings':return '<span class="canopy-openings"></span>';
 case 'harvest':return svg('<path class="harvest-route" d="M15 85Q20 55 48 48T82 15" fill="none" stroke="#ffcb75" stroke-width=".9" stroke-dasharray="2 2"/><circle cx="25" cy="68" r="2" fill="#e3ad53"/><circle cx="53" cy="45" r="2" fill="#e3ad53"/>');
 case 'water':return svg('<path class="river-flow" d="M35 0Q60 28 40 50T55 100" fill="none" stroke="#7bdcff" stroke-width=".8" stroke-dasharray="4 8"/>');
 case 'nursery':return svg('<path d="M45 35Q70 29 82 50L78 77Q55 82 40 67Z" stroke="#f8df96" stroke-width="1" stroke-dasharray="3 2" fill="#69b2d744"/><circle class="stock-ripple" cx="61" cy="57" r="8" stroke="#c7f6ff" stroke-width=".5" fill="none"/>');
 case 'fishing':return svg('<path d="M20 48L65 40L74 72L27 80ZM25 52L70 63M28 60L71 70M35 47L42 77M48 44L55 74M60 42L66 72" stroke="#f1ddbd" stroke-width=".7" fill="#c19e7040"/>');
 case 'bank':return '<span class="bank-vegetation"></span>';
 case 'treatment':return svg('<rect x="72" y="64" width="15" height="12" rx="1" fill="#c5e2dd" stroke="#a7cbd8" stroke-width="1"/><path class="water-flow" d="M52 68H71m17 0h12" stroke="#8de3ff" stroke-width="1.5" stroke-dasharray="2 3"/>');
 case 'cooperative':return svg('<path class="harvest-route" d="M20 78Q55 40 81 68M20 78Q53 87 81 68" fill="none" stroke="#ffda8f" stroke-width="1.2" stroke-dasharray="3 3"/>');
 case 'brigade':return svg('<path d="M10 14H90V90H10Z" stroke="#ffb37d" stroke-width="1.3" stroke-dasharray="4 4" fill="none"/><circle cx="18" cy="22" r="3" fill="#eb7d43"/>');
 case 'dry':return '<span class="dry-soil"></span>';
 default:return '';}}
export function sceneHTML(s,id,{compact=false,animate=false}={}){const spec=sceneSpec(s,id);return `<div class="living-scene ${compact?'scene-compact':''} ${animate?'scene-arriving':''}" data-scene="${spec.key}" data-layers="${spec.layers.join(' ')}" aria-hidden="true"><div class="scene-base terrain" style="${spec.base}"></div>${spec.layers.map(l=>`<span class="scene-layer layer-${l}">${layerHTML(l,compact)}</span>`).join('')}</div>`;}
const threshold={food:.1,regulation:.05,support:.05,cultural:.75};
const dir=(value,key)=>Math.abs(value)<threshold[key]?'flat':value>0?'up':'down';
const named=[['food','Provisão','Alimentos e produtos'],['regulation','Regulação','Água e proteção'],['support','Suporte','Solo e habitat'],['cultural','Culturais','Vivência e aprendizagem']];
export function impactReport(before,after,id,action){const now0=metrics(before),now1=metrics(after),future0=structuredClone(before),future1=structuredClone(after);let steps=0;for(let i=0;i<Math.min(2,6-before.round);i++){advance(future0);advance(future1);steps++;}const later0=metrics(future0),later1=metrics(future1);const services=named.map(([key,name,process])=>{const immediate=dir(now1[key]-now0[key],key),later=dir(later1[key]-later0[key],key);return {key,name,process,immediate,later,phase:immediate!=='flat'?'now':later!=='flat'?'later':'none',direction:immediate!=='flat'?immediate:later};});
 const connections=[];for(const n of neighbors(id)){if(!['crop','agro'].includes(after.tiles[n].type))continue;const a=local(before,n),b=local(after,n);if(Math.abs(b.poll-a.poll)>.1)connections.push({id:n,kind:'pollination',direction:b.poll>a.poll?'up':'down',label:b.poll>a.poll?'Mais apoio à polinização':'Menos apoio à polinização'});}
 const waterDelta=now1.water-now0.water,availability=now1.waterAvailability-now0.waterAvailability;if(Math.abs(waterDelta)>.05||Math.abs(availability)>.05){for(const t of after.tiles.filter(t=>['wetland','village'].includes(t.type)&&t.id!==id))connections.push({id:t.id,kind:Math.abs(availability)>Math.abs(waterDelta)?'supply':'water',direction:(Math.abs(availability)>Math.abs(waterDelta)?availability:waterDelta)>0?'up':'down',label:Math.abs(availability)>Math.abs(waterDelta)?(availability>0?'Mais água disponível':'Maior retirada de água'):(waterDelta>0?'Menor pressão sobre a água':'Resíduos ou sedimentos na água')});}
 if(action==='cooperative')for(const t of after.tiles.filter(t=>['crop','agro','pasture','silvo'].includes(t.type)))connections.push({id:t.id,kind:'livelihood',direction:'up',label:'Produtos ligados à compra local'});
 return {id,action,round:before.round+1,services,connections,steps,beforeScene:sceneSpec(before,id),afterScene:sceneSpec(after,id)};}
export function serviceCards(report,{compact=false}={}){return `<div class="impact-services ${compact?'impact-services-compact':''}">${report.services.map(s=>{const direction=s.direction,icon=direction==='up'?'↑':direction==='down'?'↓':'—',label=s.phase==='none'?'Sem mudança direta':s.phase==='later'?'Resposta gradual':direction==='up'?'Amplia neste ciclo':'Reduz neste ciclo',laterShift=s.phase==='now'&&s.later!==s.immediate&&s.later!=='flat';return `<div class="impact-service ${direction}" data-service="${s.key}" data-phase="${s.phase}"><span class="service-symbol" aria-hidden="true">${icon}</span><div><strong>${s.name}</strong><small>${s.process}</small><span class="effect-direction">${label}${laterShift?(s.later==='up'?' · depois tende a ampliar':' · depois tende a reduzir'):''}</span></div></div>`;}).join('')}</div>`;}
export const ACTION_FEEDBACK={
 cover:['Palhada aplicada','A superfície agora tem cobertura; o solo e a ciclagem de nutrientes respondem ao longo dos ciclos.'],notill:['Semeadura localizada','Os sulcos indicam mínimo revolvimento. A proteção completa depende de combinar cobertura e rotação.'],crop_rotation:['Cultivos diversificados','A área passa a alternar espécies. O cenário representa a organização do sistema; uma nova cultura não cresce instantaneamente.'],biocontrol:['Faixas floridas implantadas','As bordas oferecem recursos e refúgios. Os pontos em movimento representam o processo de polinização.'],drip:['Linhas de gotejamento instaladas','A água chega à cultura e sua retirada passa a afetar o recurso compartilhado.'],compost:['Composto distribuído','A matéria orgânica foi adicionada. A atividade dos decompositores e a recuperação do solo são graduais.'],bio_growth:['Agentes aplicados ao solo','A animação destaca a interação com as raízes; ela não representa crescimento instantâneo das plantas.'],microbial:['Agente de controle aplicado','A ação sobre o inseto-alvo se manifesta quando há pressão de herbivoria.'],mip:['Monitoramento ativado','O cultivo mantém sua estrutura física; o que muda é a observação e a resposta seletiva às pragas.'],fertilizer:['Nutrientes adicionados','A cultura passa a ter nutrientes disponíveis; chuva e cobertura mudam o risco de transporte para a água.'],spray:['Aplicação e resíduos visíveis','A pulverização chega ao cultivo. A ligação com outros setores destaca a exposição de organismos não alvo e da água.'],rotation:['Piquetes reorganizados','As cercas delimitam áreas de descanso. A recuperação da forragem exige tempo.'],silvo:['Árvores implantadas no pasto','O cenário começa com árvores jovens; sombra e produtos das árvores crescem com o sistema.'],agro:['Sistema com árvores implantado','A imagem mostra a implantação. A produção e a cobertura se recompõem durante os ciclos.'],restore:['Vegetação em recuperação','O setor começa com vegetação jovem. Não se transforma imediatamente em uma floresta antiga.'],to_crop:['Uso convertido em agricultura','A estrutura do uso mudou. A imagem representa o cultivo instalado; a colheita continua dependente do tempo e das relações ecológicas.'],to_pasture:['Uso convertido em pastagem','A paisagem passa à criação. O modo de manejar a forragem e o solo alterará sua trajetória.'],rewet:['Espaço devolvido à água','A área produtiva cede espaço à planície alagável. O estoque de peixes ainda precisará se recuperar.'],bank:['Margem revegetada','A borda ganha vegetação em implantação; seu efeito depende também do manejo dos outros setores.'],nursery:['Refúgio pesqueiro delimitado','O espaço de reprodução fica protegido. O aumento de peixes depende dos ciclos seguintes.'],fish:['Captura ampliada','A rede representa maior retirada. A reposição do estoque não é instantânea.'],timber:['Retirada seletiva realizada','As clareiras mostram a retirada de parte das árvores. O estoque remanescente e sua reposição continuam importantes.'],gather:['Rota de coleta organizada','A cobertura florestal permanece. Muda o uso dos frutos e das sementes e sua disponibilidade para outros organismos.'],trail:['Trilha instalada','O acesso cria uma oportunidade de aprendizagem e visitação; a qualidade da experiência depende da paisagem.'],sanitation:['Tratamento implantado','O fluxo tratado muda a pressão local sobre a água; a bacia ainda recebe efeitos dos outros setores.'],cooperative:['Rede local organizada','A estrutura da vegetação permanece. As conexões destacam o acesso aos produtos do território.'],brigade:['Resposta comunitária organizada','A marcação representa a área de prevenção e resposta. O efeito se manifesta no evento de incêndio.'],keep:['Uso mantido','Não houve nova alteração estrutural. O clima, a vizinhança e as decisões anteriores continuam atuando.']};
